// RouletteWheel.jsx
import React, { useEffect, useRef, useState } from 'react';
import { spinRoulette } from '../api/rouletteApi';

/**
 * SVG 기반 룰렛 휠 구현
 * - segments: 서버에서 발생 가능한 브랜드/꽝 항목과 매핑
 * - 서버 결과(쿠폰.brand)를 받아 해당 세그먼트로 도착하도록 회전
 */
const segments = [
  { label: 'BrandA 30%', key: 'BrandA' },
  { label: 'BrandB 20%', key: 'BrandB' },
  { label: 'BrandC 10%', key: 'BrandC' },
  { label: '꽝', key: 'nothing' },
  { label: '꽝', key: 'nothing2' },
  { label: '꽝', key: 'nothing3' },
];

function degToRad(d) { return (d * Math.PI) / 180; }

function RouletteWheel() {
  const [spinning, setSpinning] = useState(false);
  const [result, setResult] = useState(null);
  const wheelRef = useRef(null);
  const [rotation, setRotation] = useState(0);

  const handleSpin = async () => {
    if (spinning) return;
    setSpinning(true);
    setResult(null);

    try {
      const res = await spinRoulette();
      const payload = res.data;

      // 어떤 세그먼트로 도착할지 결정
      let targetIndex = 0;
      if (payload.type === 'coupon' && payload.coupon && payload.coupon.brand) {
        const brand = payload.coupon.brand;
        // 동일 브랜드를 가진 세그먼트 찾기
        const idx = segments.findIndex(s => s.key.toLowerCase() === brand.toLowerCase());
        targetIndex = idx >= 0 ? idx : 0;
      } else {
        // 꽝 중 랜덤 선택
        const missIndices = segments.map((s,i) => ({s,i})).filter(x=>x.s.key.startsWith('nothing')).map(x=>x.i);
        targetIndex = missIndices[Math.floor(Math.random()*missIndices.length)];
      }

      // 애니메이션: 여러 바퀴 돌리고 목표 각도로 정지
      const segmentAngle = 360 / segments.length;
      // 목표 각도 중앙으로 맞춤
      const randomOffset = (Math.random() * (segmentAngle - 8)) - (segmentAngle/2 - 4);
      const targetAngle = 360 * (2 + Math.floor(Math.random()*3)) + (360 - (targetIndex * segmentAngle) - segmentAngle/2) + randomOffset;

      // apply transform with transition
      const wheel = wheelRef.current;
      if (wheel) {
        wheel.style.transition = 'transform 4s cubic-bezier(.12,.7,.12,1)';
        wheel.style.transform = `rotate(${targetAngle}deg)`;
        setRotation(targetAngle % 360);
      }

      // 애니메이션 끝난 뒤 결과 보여주기
      setTimeout(() => {
        setSpinning(false);
        setResult(payload);
      }, 4200);

    } catch (err) {
      setSpinning(false);
      setResult({ success: false, message: err.response?.data?.message || err.message || '서버 에러' });
    }
  };

  // wheel SVG 렌더링
  const radius = 140;
  const center = radius + 4;

  return (
    <div style={{ padding: 20, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <div style={{ position: 'relative', width: (radius*2)+8, height: (radius*2)+8 }}>
        <svg width={(radius*2)+8} height={(radius*2)+8} viewBox={`0 0 ${center*2} ${center*2}`}>
          <g ref={wheelRef} transform={`translate(${center},${center})`} style={{ transformOrigin: 'center center' }}>
            {segments.map((seg, i) => {
              const angle = 360 / segments.length;
              const start = i * angle;
              const largeArc = angle > 180 ? 1 : 0;
              const x1 = center + radius * Math.cos(degToRad(start));
              const y1 = center + radius * Math.sin(degToRad(start));
              const x2 = center + radius * Math.cos(degToRad(start + angle));
              const y2 = center + radius * Math.sin(degToRad(start + angle));
              const path = `M ${0} ${0} L ${radius * Math.cos(degToRad(start))} ${radius * Math.sin(degToRad(start))} A ${radius} ${radius} 0 ${largeArc} 1 ${radius * Math.cos(degToRad(start + angle))} ${radius * Math.sin(degToRad(start + angle))} Z`;
              const fill = seg.key.startsWith('nothing') ? '#f5f5f5' : (i % 2 === 0 ? '#ffecb3' : '#ffe0b2');
              return (
                <g key={seg.key + i}>
                  <path d={path} fill={fill} stroke="#ddd" transform={`rotate(${0})`} />
                  <text x={(radius/2) * Math.cos(degToRad(start + angle/2))} y={(radius/2) * Math.sin(degToRad(start + angle/2))} fill="#333" fontSize={12} textAnchor="middle" alignmentBaseline="middle" transform={`rotate(${start + angle/2})`}>
                    {seg.label}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>

        {/* pointer */}
        <div style={{ position: 'absolute', left: '50%', top: -6, transform: 'translateX(-50%)', width: 0, height: 0, borderLeft: '12px solid transparent', borderRight: '12px solid transparent', borderBottom: '18px solid #ff5252' }} />
      </div>

      <button onClick={handleSpin} disabled={spinning} style={{ marginTop: 16, padding: '10px 20px', borderRadius: 8, background: '#0070f3', color: '#fff', border: 'none' }}>
        {spinning ? '돌리는 중...' : '룰렛 돌리기'}
      </button>

      {result && (
        <div style={{ marginTop: 16, padding: 12, borderRadius: 8, boxShadow: '0 6px 16px rgba(0,0,0,0.06)', width: 360 }}>
          <h4 style={{ margin: 0 }}>{result.success ? '축하합니다!' : '결과'}</h4>
          <p style={{ marginTop: 8 }}>{result.message}</p>
          {result.coupon && (
            <div>
              <div>쿠폰 코드: <strong>{result.coupon.code}</strong></div>
              <div>브랜드: {result.coupon.brand} | 할인: {result.coupon.discount}%</div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default RouletteWheel;
